def adjacent_differences(values):
    if len(values) < 2:
        return []
    differences = []
    for i in range(1, len(values)):
        differences.append(values[i] - values[i - 1])
    return differences

def even_first(values):
    """
    Returns a new list with all even integers followed by all odd integers,
    preserving the original order within each group. Handles empty input.
    """
    evens, odds = ([], [])
    for value in values:
        if value % 2 == 0:
            evens.append(value)
        else:
            odds.append(value)
    return evens + odds
